using Godot;using Hmi.Core;using Hmi.GodotAdapter;using System;using System.Text.Json;using System.Reflection;using System.Linq;
public partial class ProjectileAdapterProbe:Node
{
 int checks;bool done;void C(bool b,string s){checks++;if(!b)throw new Exception(s);}void Near(Vector3 a,Vector3 b,string s)=>C(a.DistanceTo(b)<.00002f,s);
 public override void _Ready(){try{Run();done=true;}catch(Exception e){GD.PushError(e.ToString());GetTree().Quit(1);}}
 public override void _Process(double delta){if(done)GetTree().Quit();}
 void Run(){var content=JsonSerializer.Deserialize<GameContent>(FileAccess.GetFileAsString("res://content/gameplay.json"),new JsonSerializerOptions{PropertyNameCaseInsensitive=true});var sim=new GameSimulation(content);string hero=OS.GetEnvironment("PROJECTILE_PROBE_HERO");if(hero.Length==0)hero="crit";sim.StartRun(hero,1030);var parent=new Node3D();AddChild(parent);var fx=new ProjectilePresentation(parent);int launches=0,impacts=0,ric=0,comp=0,pending=0,reuses=0;var old=new System.Collections.Generic.Dictionary<int,ProjectileId>();bool pausedCheck=false;var lines=new System.Collections.Generic.List<string>();
 for(int frame=0;frame<900&&sim.Phase==RunPhase.Combat;frame++){sim.Step();fx.CaptureStep(sim,e=>launches++);long cap=fx.Captured;fx.CaptureStep(sim,e=>throw new Exception("duplicate launch callback"));C(fx.Captured==cap,"same transition buffer dedup");for(int j=0;j<sim.ProjectileTransitionCount;j++){var e=sim.GetProjectileTransition(j);if(e.Kind==ProjectileTransitionKind.Impact)impacts++;}
 foreach(float alpha in new[]{0f,.5f,1f}){fx.Reconcile(sim,alpha,false,true);C(fx.ActiveCount==sim.ProjectileCount,"all authority live bodies represented");foreach(var draw in fx.Inspect()){C(sim.TryGetProjectile(draw.Id,sim.RunToken,sim.Wave,out var view),"exact scoped identity");var a=new Vector3(view.PreviousPosition.X,ProjectilePresentation.DisplayY,view.PreviousPosition.Y);var b=new Vector3(view.Position.X,ProjectilePresentation.DisplayY,view.Position.Y);Near(draw.Body,a.Lerp(b,alpha),"body interpolates actual segment only");if(draw.TailVisible){Near(draw.TailEnd,draw.Body,"tail ends at rendered body");C(draw.TailStart.DistanceTo(draw.TailEnd)<=.30002f,"bounded short trail");}if(view.State==ProjectileState.ContinuationPending){pending++;Near(a,b,"pending contact stationary");C(!draw.TailVisible,"no across-bounce tail");}if(view.Kind==ProjectileKind.Ricochet)ric++;else comp++;if(old.TryGetValue(view.Id.Index,out var id)&&id!=view.Id)reuses++;old[view.Id.Index]=view.Id;}}
 if(fx.ActiveCount>0&&!pausedCheck){fx.Reconcile(sim,.25f,false,true);var before=fx.Inspect();fx.Reconcile(sim,.9f,true,true);var after=fx.Inspect();C(before.Length==after.Length,"pause count");for(int p=0;p<before.Length;p++){C(before[p].Id==after[p].Id&&before[p].Hits==after[p].Hits&&before[p].TailVisible==after[p].TailVisible,"pause identity");Near(before[p].Body,after[p].Body,"pause position");Near(before[p].TailStart,after[p].TailStart,"pause tail start");Near(before[p].TailEnd,after[p].TailEnd,"pause tail end");}long beforeCount=fx.Captured;fx.ClearPresentation();C(fx.ActiveCount==0,"hidden clear");fx.CaptureStep(sim,e=>throw new Exception("hidden same buffer launch replay"));C(fx.Captured==beforeCount,"hidden retains event watermark");fx.Reconcile(sim,.25f,false,true);C(fx.ActiveCount==sim.ProjectileCount,"resume rehydrates live snapshot not launch event");pausedCheck=true;}
 lines.Add($"{frame}\t{sim.Tick}\t{sim.Phase}\t{sim.ProjectileCount}\t{fx.ActiveCount}\t{sim.ProjectileTransitionCount}");
 }
 C(launches>0&&impacts>0&&(hero=="crit"?ric>0:comp>0),"natural crit and companion launch flight and impact coverage");if(hero=="crit")C(pending>0,"natural next-leg continuation observed");C(reuses>0,"natural projectile slot generations reused");sim.PrepareRun("crit",1031);fx.Reconcile(sim,1,false,true);C(fx.ActiveCount==0,"prepared new scope clears all bodies");fx.Dispose();fx.Dispose();fx.CaptureStep(sim,_=>throw new Exception());fx.Reconcile(sim,1,false,true);C(fx.ActiveCount==0,"disposed repeated calls inert");parent.QueueFree();var outpath=OS.GetEnvironment("PROJECTILE_PROBE_OUT");if(outpath.Length>0)System.IO.File.WriteAllLines(outpath,lines);GD.Print($"PROJECTILE_ADAPTER_PASS {checks} launches={launches} impacts={impacts} ricSamples={ric} companionSamples={comp} pendingSamples={pending} generationChanges={reuses}");
 }
